    openStream: {
        parameters: {
            query: {
                /** @description From `POST /stream/ticket`. Valid until it expires, not consumed by this request. */
                ticket: string;
                /** @description One of the `streamFormats` from `GET /capabilities`. Omit it to get the first, which is the best this install offers. A format the install does not encode is a `400` rather than a silent substitution. */
                format?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /**
             * @description Audio, until something ends it. `Cache-Control` is `no-store`, there is no
             *     `Content-Length`, and `Accept-Ranges` is `none` — a live stream has no length
             *     to take a range of, and a `Range` request is answered with the stream from the
             *     live edge like any other.
             */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "audio/ogg": string;
                    "audio/aac": string;
                };
            };
            /** @description A format this install does not encode. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description No ticket, an unknown ticket, or an expired one. All three answer identically, so a caller cannot sort guesses into wrong and too late. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            503: components["responses"]["StreamUnavailable"];
        };
    };
